pm.test("Статус відповіді 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Відповідь містить масив товарів", function () {
    const json = pm.response.json();
    pm.expect(json.data).to.be.an("array");
});

pm.test("У базі 12 товарів", function () {
    const json = pm.response.json();
    pm.expect(json.meta.total).to.eql(12);
});

pm.test("На сторінці 9 товарів", function () {
    const json = pm.response.json();
    pm.expect(json.data.length).to.eql(9);
});

pm.test("Пагінація присутня", function () {
    const json = pm.response.json();
    pm.expect(json).to.have.property("links");
    pm.expect(json).to.have.property("meta");
});

const expectedStatus = Number(
    pm.variables.get("expected_status") || 200
);

pm.test("Правильний HTTP-статус", function () {
    pm.response.to.have.status(expectedStatus);
});

pm.test("Відповідь у форматі JSON", function () {
    pm.response.to.be.json;
});

if (expectedStatus === 200) {
    pm.test("Відповідь містить дані", function () {
        const json = pm.response.json();
        pm.expect(json).to.have.property("data");
    });
}

if (expectedStatus === 422) {
    pm.test("Помилка валідації", function () {
        const json = pm.response.json();
        pm.expect(json).to.have.property("errors");
    });
}

